/*
 * prog54_topo_sort – reconstructed from the obfuscated binary
 *
 * The original binary implements a very small topological‑sort utility.
 * It expects two integer arguments N and M (0 ≤ N,M ≤ 8) followed by M
 * directed edges (u v) read from *stdin*.  Vertices are numbered 0 … N‑1.
 *
 * Behaviour:
 *   * If N or M is out of the allowed range, or any edge contains a
 *     vertex outside 0 … N‑1, the program prints
 *
 *         INVALID_INPUT\n
 *     and returns exit status 1.
 *
 *   * If the directed graph contains a cycle, the program prints the
 *     (partial) topological ordering that was produced, a newline, then
 *     "CYCLE\n" and returns exit status 1.
 *
 *   * Otherwise it prints one possible topological ordering of the
 *     vertices.  Numbers are separated by a single space, a final
 *     newline is printed, and the program returns exit status 0.
 *
 * The implementation below follows the logic of the original binary
 * but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8          /* maximum number of vertices allowed by the original program */

int main(int argc, char *argv[])
{
    /* -------------------------------------------------------------
       1. Parse command‑line arguments (N and M)
       ------------------------------------------------------------- */
    if (argc != 3) {
        puts("INVALID_INPUT");
        return 1;
    }

    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n < 0 || n > MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }

    long m = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0' || m < 0 || m > MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* -------------------------------------------------------------
       2. Read the edges
       ------------------------------------------------------------- */
    int adj[MAXV][MAXV] = {0};   /* adjacency matrix */
    int indeg[MAXV] = {0};

    for (long i = 0; i < m; ++i) {
        int u, v;
        if (scanf("%d %d", &u, &v) != 2) {
            puts("INVALID_INPUT");
            return 1;
        }
        if (u < 0 || u >= n || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        /* store the edge; duplicate edges are ignored (they do not affect
           indegree counts in the original program) */
        if (!adj[u][v]) {
            adj[u][v] = 1;
            ++indeg[v];
        }
    }

    /* -------------------------------------------------------------
       3. Kahn’s algorithm (queue implemented with a simple array)
       ------------------------------------------------------------- */
    int queue[MAXV];
    int qhead = 0, qtail = 0;          /* indices for a simple FIFO */
    int processed = 0;                 /* number of vertices output */

    for (int v = 0; v < n; ++v) {
        if (indeg[v] == 0) {
            queue[qtail++] = v;
        }
    }

    int first_output = 1;              /* used to control spaces */

    while (qhead < qtail) {
        int u = queue[qhead++];
        if (!first_output) putchar(' ');
        printf("%d", u);
        first_output = 0;
        ++processed;

        for (int v = 0; v < n; ++v) {
            if (adj[u][v]) {
                if (--indeg[v] == 0) {
                    queue[qtail++] = v;
                }
            }
        }
    }

    putchar('\n');

    /* -------------------------------------------------------------
       4. Detect a cycle (i.e. not all vertices were processed)
       ------------------------------------------------------------- */
    if (processed != n) {
        puts("CYCLE");
        return 1;
    }

    return 0;
}
